// Writes content/units/y12-english-essay-writing/answers.ts from the reviewed essay content (spec 011 T073, content-prompt.md).
// Inputs stay in gitignored resources/; only the generated file is committed.
//
//   npm run english-essay-build-answers                 (writes the file for every approved essay)
//   npm run english-essay-build-answers -- --dry-run    (prints what it would write, changes nothing)
//
// Inputs:
//   resources/english-essay/content/<id>.json   one per essay, id e1 to e6:
//     { "markingNotes": string, "modelEssay": string, "conceptTags": ["skill-thesis", "away-symbols", ...] }   (`concepts` is accepted too)
//     `conceptTags` are keys of the unit's single concept record (content/units/y12-english-essay-writing/concepts.ts); this script
//     turns them into full concept ids.
//   resources/english-essay/review/approved.json   ["e1", "e3", ...]: the essays Chiang has approved in the review report.
//
// It refuses a model essay outside 900 to 1,100 words, a concept key that is not on the list, empty marking notes, and any model
// quotation the local play does not contain exactly (the deterministic quote check, zero flags). It prints local flags and word
// counts and never sets `live`: that is a one-line change in questions.ts, made only after the marker gate.

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import { ENGLISH_ESSAY_CONCEPTS } from "../content/units/y12-english-essay-writing/concepts";
import { questions } from "../content/units/y12-english-essay-writing/questions";
import { checkModelEssay, modelProblems } from "../lib/english-essay/model-check";
import { PlayIndex } from "../lib/english-essay/play-index";

const UNIT = "y12-english-essay-writing";
const ROOT = process.cwd();
const CONTENT = join(ROOT, "resources", "english-essay", "content");
const APPROVED = join(ROOT, "resources", "english-essay", "review", "approved.json");
const PLAY = join(ROOT, "resources", "english-unseen", "away-by-michael-gow.txt");
const OUT = join(ROOT, "content", "units", UNIT, "answers.ts");
const DRY = process.argv.includes("--dry-run");

interface Input {
  markingNotes: string;
  modelEssay: string;
  conceptTags?: string[];
  concepts?: string[];
}

function fail(message: string): never {
  console.error(`✗ ${message}`);
  process.exit(1);
}

if (!existsSync(APPROVED)) fail(`No ${APPROVED}: nothing has been approved yet.`);
if (!existsSync(PLAY)) fail(`The local play ${PLAY} is missing (it is gitignored): the model quotations cannot be checked.`);
const approved = JSON.parse(readFileSync(APPROVED, "utf8")) as string[];
if (!Array.isArray(approved) || approved.some((id) => !/^e[1-6]$/.test(id))) fail("approved.json must be a list of essay ids e1 to e6.");
const play = new PlayIndex(readFileSync(PLAY, "utf8"));
const questionOf = new Map(questions.map((q) => [q.id, q.prompt]));

const entries: string[] = [];
const problems: string[] = [];
for (const id of [...new Set(approved)].sort()) {
  const file = join(CONTENT, `${id}.json`);
  if (!existsSync(file)) fail(`${id} is approved but ${file} does not exist.`);
  const raw = JSON.parse(readFileSync(file, "utf8")) as Input;
  const e = { ...raw, concepts: raw.conceptTags ?? raw.concepts ?? [] };
  if (!e.markingNotes?.trim()) fail(`${id}: markingNotes is empty.`);
  if (!Array.isArray(e.concepts) || e.concepts.length === 0) fail(`${id}: no concept keys.`);
  for (const k of e.concepts) if (!(k in ENGLISH_ESSAY_CONCEPTS)) fail(`${id}: concept key "${k}" is not on the unit's concept list.`);
  const qid = `${UNIT}.${id}`;
  const check = checkModelEssay(e.modelEssay ?? "", questionOf.get(qid) ?? "", play);
  problems.push(...modelProblems(id, check));
  console.log(`${id}: ${check.words} words, ${check.quotations} quotation(s), ${check.flags.length} flag(s), ${e.concepts.length} concept tag(s)`);
  entries.push(
    `  [\`\${UNIT}.${id}\`]: {\n    rubric: [],\n    englishEssay: {\n      markingNotes: ${JSON.stringify(e.markingNotes)},\n      modelEssay: ${JSON.stringify(e.modelEssay)},\n      conceptTags: ${JSON.stringify(e.concepts.map((k) => `${UNIT}.c-${k}`))},\n    },\n  },`,
  );
}
if (problems.length > 0) {
  console.error(`\n✗ ${problems.length} problem(s); nothing written:`);
  for (const p of problems) console.error(`  - ${p}`);
  process.exit(1);
}

const file = `import type { AnswerSet } from "@/lib/types";

// SERVER ONLY — the English essays' keys (constitution Principle I): the marking notes, the band 1 model essay and the key
// concept tags. GENERATED by \`npm run english-essay-build-answers\` from the reviewed content in
// resources/english-essay/content/; do not edit by hand. An essay without a key stays \`live: false\`; a non-live essay may
// have no key at all (spec 011 data-model §1.2).

const UNIT = "${UNIT}";

export const answers: AnswerSet = {
${entries.join("\n")}
};
`;

if (DRY) {
  console.log(`\n(dry run) would write ${entries.length} essay key(s) to ${OUT}`);
} else {
  writeFileSync(OUT, file, "utf8");
  console.log(`\n✓ Wrote ${entries.length} essay key(s) to content/units/${UNIT}/answers.ts. Next: set live: true in questions.ts for each one the marker gate has passed, then run the full chain.`);
}
